"""Interactive widgets — widgets the user acts on."""

from __future__ import annotations

from typing import Any, Callable, Literal

from workpeg.ui.actions import Action
from workpeg.ui.state import Binding
from workpeg.ui.widgets.base import BaseWidget


class Button(BaseWidget):
    """A Pegment design-system button (``buttons.css``).

    Variants — the visual treatment::

        Button("Save")                              # primary (default)
        Button("Cancel",    variant="ghost")
        Button("Duplicate", variant="secondary")
        Button("Settings",  variant="tertiary")     # outlined
        Button("Reply",     variant="secondary-ghost")
        Button("Skip",      variant="text")         # inline, no padding
        Button("Learn more", variant="link")        # underlined-link colour

    ``error=True`` layers the critical/danger treatment onto **any** variant,
    and replaces the old ``variant="destructive"``::

        Button("Delete",  error=True)                    # critical primary
        Button("Discard", variant="ghost", error=True)   # critical ghost

    Modifiers: ``size`` (``"sm"`` | ``"md"`` | ``"lg"``), ``rounded`` (full
    pill), ``dot`` (a leading ``currentColor`` status dot), ``full_width``
    (stretch to the container), and ``icon`` — a Tabler icon inside the button.
    With a label the icon sits on the ``icon_position`` side
    (``"left"`` default / ``"right"``); with no label it renders icon-only, so
    give it an ``aria_label``::

        Button("Add",  icon="plus")
        Button("Next", icon="arrow-right", icon_position="right")
        Button("",     icon="trash", aria_label="Delete", variant="ghost")
    """

    widget_type = "Button"

    #: The design-system families (pegment.css). ``error=`` is a modifier on
    #: top of these, not a family of its own.
    #:
    #: TWO NAMES FOR MOST OF THEM, and both are permanent. The design system
    #: renamed every family; ``pegment.css`` answers to both by giving each
    #: pair ONE shared declaration body, so neither is a copy that can drift.
    #: The old names are not deprecated: ``ai.js`` and ``scaffold.js``
    #: hard-code these class strings and reach deployed pegs out of band,
    #: while ``pegment.css`` is bundled and reaches them only on a rebuild —
    #: so an old name is a live contract, not a migration artefact.
    #:
    #: The rename is NOT a restyle. ``text``/``link-gray`` keep pegment's
    #: tone rather than the (darker) upstream one, so no existing caller
    #: changes appearance.
    LEGACY_VARIANTS = {
        "secondary": "secondary-color",
        "tertiary": "outline-gray",
        "ghost": "ghost-gray",
        "secondary-ghost": "ghost-color",
        "text": "link-gray",
        "link": "link-color",
    }

    #: The nine families the design system names.
    FAMILIES = (
        "primary",
        "secondary-color",
        "secondary-gray",
        "outline-gray",
        "outline-color",
        "ghost-gray",
        "ghost-color",
        "link-gray",
        "link-color",
    )

    #: Everything ``variant=`` accepts: the nine families plus the seven
    #: names that predate them. Ordered old-first so the tuple reads as the
    #: history it is.
    VARIANTS = (
        "primary",
        "secondary",
        "tertiary",
        "ghost",
        "secondary-ghost",
        "text",
        "link",
    ) + FAMILIES[1:]

    #: ``error=`` has a defined appearance on these five and nowhere else —
    #: a design decision, not an unfinished stylesheet. On any other family
    #: the class is inert, so the button renders as though ``error`` were
    #: never passed. Listed by BOTH names, since either may be given.
    ERROR_FAMILIES = frozenset({
        "primary",
        "secondary", "secondary-color",
        "tertiary", "outline-gray",
        "ghost", "ghost-gray",
        "text", "link-gray",
    })

    def __init__(
        self,
        label: str | Binding = "",
        *,
        on_click: Callable | None = None,
        action: Action | None = None,
        variant: Literal[
            # the seven that predate the design-system rename
            "primary",
            "secondary",
            "tertiary",
            "ghost",
            "secondary-ghost",
            "text",
            "link",
            # and the nine families it names
            "secondary-color",
            "secondary-gray",
            "outline-gray",
            "outline-color",
            "ghost-gray",
            "ghost-color",
            "link-gray",
            "link-color",
        ] = "primary",
        size: Literal["sm", "md", "lg"] = "md",
        error: bool = False,
        rounded: bool = False,
        dot: bool = False,
        full_width: bool = False,
        kind: Literal["button", "submit"] = "button",
        aria_label: str = "",
        icon: str | None = None,
        icon_position: Literal["left", "right"] = "left",
        key: str | None = None,
        visible: bool | Binding = True,
        disabled: bool | Binding = False,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key,
            visible=visible,
            disabled=disabled,
            metadata=metadata,
        )
        self.label = label
        self.on_click = on_click
        self.action = action
        self.variant = variant
        self.size = size
        self.error = error
        self.rounded = rounded
        self.dot = dot
        self.full_width = full_width
        self.kind = kind
        self.aria_label = aria_label
        self.icon = icon
        self.icon_position = icon_position

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {
            "label": self.label,
            "action": self.action,
            "variant": self.variant,
            "size": self.size,
            "full_width": self.full_width,
        }
        if self.error:
            p["error"] = True
        if self.rounded:
            p["rounded"] = True
        if self.dot:
            p["dot"] = True
        if self.aria_label:
            # camelCase — the key the generator/runtime read (props.ariaLabel).
            p["ariaLabel"] = self.aria_label
        if self.icon is not None:
            p["icon"] = self.icon
            if self.icon_position != "left":
                p["icon_position"] = self.icon_position
        return p


class ButtonGroup(BaseWidget):
    """Buttons fused into one bar — the design system's button group
    (``button-group.css``), the row of quick ranges above a calendar panel
    ("Today · Week · Monday"). A hairline sits between each pair and only
    the two outer ends are rounded.

    **Its content is its children**, and every child is a :class:`Button`
    with its own label and ``on_click``. A group is a row of actions, not
    a choice: nothing in it stays pressed (that is a
    :class:`ToggleGroup`), and each button is its own Tab stop::

        ButtonGroup(
            Button("Today", on_click=self.today),
            Button("Week", on_click=self.week),
            Button("Monday", on_click=self.monday),
            variant="tertiary-gray", rounded=True, label="Quick ranges",
        )

    ``variant``, ``size``, ``rounded`` and ``disabled`` set on the group
    reach every button that does not set its own, so ``Button("Week",
    variant="primary")`` keeps its family; a disabled group disables every
    button in it. ``variant`` takes any of :attr:`Button.VARIANTS` and one
    family that exists only here, ``"tertiary-gray"`` (a filled grey pill
    on the design's sunken surface) — a ``Button`` standing alone cannot
    name it, which keeps ``Button`` at its nine families. ``fill``
    stretches the group across its container and splits it evenly between
    the buttons, as a :class:`CalendarCard` column does for any group in
    it. ``label`` is the group's accessible name. ``variant`` and ``size``
    are literals; ``rounded``, ``fill``, ``disabled`` and ``label`` may
    come from state.
    """

    widget_type = "ButtonGroup"

    #: The families a button may name only inside a group. THREE COPIES:
    #: this, the compiler's ``_BUTTON_GROUP_ONLY_VARIANTS`` and the
    #: runtime's ``BTN_GROUP_VARIANTS``, which honours one only for a
    #: button its group drew; ``tests/ui/test_button_group.py`` pins them.
    VARIANTS_GROUP_ONLY = ("tertiary-gray",)

    def __init__(
        self,
        *buttons: Button,
        variant: str | None = None,
        size: Literal["sm", "md", "lg"] | None = None,
        rounded: bool | Binding = False,
        fill: bool | Binding = False,
        label: str | Binding | None = None,
        disabled: bool | Binding = False,
        style: dict[str, Any] | None = None,
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, disabled=disabled, **kwargs)
        self.buttons = list(buttons)
        self.variant = variant
        self.size = size
        self.rounded = rounded
        self.fill = fill
        self.label = label
        self.style = style

    def children(self) -> list[Any]:
        return list(self.buttons)

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {}
        for flag in ("rounded", "fill"):
            if getattr(self, flag):
                p[flag] = getattr(self, flag)
        for name in ("variant", "size", "label", "style"):
            if getattr(self, name) is not None:
                p[name] = getattr(self, name)
        return p


class Link(BaseWidget):
    """An anchor-tag link widget.

    Compiler API::

        Link("Open docs", href="https://example.com")
        Link("New tab",   href="https://example.com", target="_blank")
        Link("Settings",  href="/settings", icon="settings")   # leading icon

    The content can be a **text label** (a string/f-string, or a state/route
    ref) or an arbitrary **widget child** — pass a widget as the first argument
    to wrap it in the anchor as a single click target::

        Link(Row(Image(src=logo), Text("Home")), href="/")
        Link(Card(...), href=f"/posts/{post['id']}")

    ``icon`` places a Tabler :class:`~workpeg.ui.Icon` (by name, no ``ti-``
    prefix) inside the anchor, before the label/child — so the whole icon+content
    is one click target.
    """

    widget_type = "Link"

    def __init__(
        self,
        label: "str | Binding | BaseWidget | None" = None,
        *,
        href: str,
        target: str | None = None,
        aria_label: str = "",
        icon: str | None = None,
        key: str | None = None,
        visible: bool | Binding = True,
        disabled: bool | Binding = False,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key,
            visible=visible,
            disabled=disabled,
            metadata=metadata,
        )
        self.label = label
        self.href = href
        self.target = target
        self.aria_label = aria_label
        self.icon = icon

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {"href": self.href}
        # A widget child is a child (see children()), not a text label.
        if not isinstance(self.label, BaseWidget):
            p["label"] = self.label
        if self.target is not None:
            p["target"] = self.target
        if self.aria_label:
            # camelCase — the key the generator/runtime read (props.ariaLabel).
            p["ariaLabel"] = self.aria_label
        if self.icon is not None:
            p["icon"] = self.icon
        return p

    def children(self) -> "list[Any]":
        return [self.label] if isinstance(self.label, BaseWidget) else []


class TextInput(BaseWidget):
    """A single-line text field, rendered as an ``<input>``.

    Inspired by Flutter's ``TextField``: a controlled value plus an
    ``on_change`` handler that receives the typed text.

    Compiler API::

        class Form(App):
            name = State("")

            def set_name(self, value):   # handlers may take the event value
                self.name = value

            def build(self):
                return TextInput(
                    value=self.name,
                    on_change=self.set_name,
                    placeholder="Your name",
                )

    Bind ``value`` to a State field and update it from ``on_change`` for a
    two-way binding. ``on_submit`` fires on Enter. ``placeholder`` is text
    like ``value``: a literal, state, a component prop or an f-string, so a
    component can pass its own hint down. ``type`` is one of
    ``"text"`` (default), ``"password"``, ``"number"``, ``"email"``,
    ``"search"``, ``"tel"``, ``"url"``, ``"date"``, ``"time"``, or
    ``"datetime-local"`` — the date/time types render a native picker and
    ``on_change`` receives an ISO-ish string (``"2026-06-16"`` for ``date``).
    """

    widget_type = "TextInput"

    def __init__(
        self,
        *,
        value: str | Binding = "",
        on_change: Callable | None = None,
        on_submit: Callable | None = None,
        placeholder: str | Binding = "",
        type: Literal[
            "text",
            "password",
            "number",
            "email",
            "search",
            "tel",
            "url",
            "date",
            "time",
            "datetime-local",
        ] = "text",
        disabled: bool = False,
        autofocus: bool = False,
        key: str | None = None,
        visible: bool | Binding = True,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key,
            visible=visible,
            disabled=disabled,
            metadata=metadata,
        )
        self.value = value
        self.on_change = on_change
        self.on_submit = on_submit
        self.placeholder = placeholder
        self.type = type
        self.autofocus = autofocus

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {
            "value": self.value,
            "type": self.type,
        }
        if self.placeholder:
            p["placeholder"] = self.placeholder
        if self.autofocus:
            p["autofocus"] = True
        return p


class Checkbox(BaseWidget):
    """A checkbox, rendered as ``<input type="checkbox">`` (wrapped in a
    ``<label>`` when ``label`` is given, so the text is clickable too).

    Inspired by Flutter's ``Checkbox``: a controlled ``checked`` value plus an
    ``on_change`` handler that receives the new boolean.

    Compiler API::

        class Prefs(App):
            subscribed = State(False)

            def set_sub(self, value):    # the handler receives the new checked
                self.subscribed = value

            def build(self):
                return Checkbox(
                    checked=self.subscribed,
                    on_change=self.set_sub,
                    label="Subscribe to the newsletter",
                )

    Bind ``checked`` to a State field and update it from ``on_change`` for a
    two-way binding. ``label`` is dynamic (f-strings, state) like ``Text``.
    """

    widget_type = "Checkbox"

    def __init__(
        self,
        *,
        checked: bool | Binding = False,
        on_change: Callable | None = None,
        label: str = "",
        disabled: bool = False,
        key: str | None = None,
        visible: bool | Binding = True,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key,
            visible=visible,
            disabled=disabled,
            metadata=metadata,
        )
        self.checked = checked
        self.on_change = on_change
        self.label = label

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {"checked": self.checked}
        if self.label:
            p["label"] = self.label
        return p


class Switch(BaseWidget):
    """An on/off toggle — Flutter's ``Switch``. Same controlled shape as
    :class:`Checkbox` (a ``checked`` binding plus an ``on_change`` receiving the
    new boolean), rendered as a sliding toggle instead of a tick box::

        class Prefs(App):
            notify = State(True)

            def set_notify(self, value):    # receives the new boolean
                self.notify = value

            def build(self):
                return Switch(checked=self.notify, on_change=self.set_notify,
                              label="Email notifications")

    ``label`` (dynamic, like ``Text``) is set via ``textContent`` — never
    ``innerHTML`` — so it can't inject markup.

    This is the design system's toggle (``toggle.html``) and renders its
    ``.toggle`` classes. ``description`` adds a second line under the label
    — the design's "full" field, where the control aligns to the top of the
    text rather than the middle of two lines. ``size`` is ``"sm"``,
    ``"md"`` (the default, and the base rule) or ``"lg"``::

        Switch(checked=self.save, on_change=self.set_save,
               label="Remember me",
               description="Save my login details for next time.")
    """

    widget_type = "Switch"

    def __init__(
        self,
        *,
        checked: bool | Binding = False,
        on_change: Callable | None = None,
        label: str = "",
        description: str = "",
        size: Literal["sm", "md", "lg"] = "md",
        disabled: bool = False,
        key: str | None = None,
        visible: bool | Binding = True,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key,
            visible=visible,
            disabled=disabled,
            metadata=metadata,
        )
        self.checked = checked
        self.on_change = on_change
        self.label = label
        self.description = description
        self.size = size

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {"checked": self.checked}
        if self.label:
            p["label"] = self.label
        if self.description:
            p["description"] = self.description
        if self.size != "md":
            p["size"] = self.size
        return p


#: The toggle button's two surfaces (``toggle-group.css``): ``default`` is a
#: filled neutral pill at rest, ``ghost`` is transparent until hovered or
#: selected. Mirrored by the compiler's ``_TOGGLE_VARIANTS`` and the
#: runtime's ``TGL_VARIANTS``; ``tests/ui/test_toggle_button.py`` pins
#: the three.
TOGGLE_VARIANTS = ("default", "ghost")

#: 32, 36 and 40px tall. ``md`` is the base rule and emits no class.
TOGGLE_SIZES = ("sm", "md", "lg")

#: Which way a :class:`ToggleGroup` lays its buttons out.
TOGGLE_DIRECTIONS = ("horizontal", "vertical")


class _NotGiven:
    """``ToggleGroup(value=…)``'s default. A group is MANAGED when ``value``
    is passed at all — and ``value=None`` is a real managed value, "nothing
    selected yet" — so ``None`` cannot double as "not passed". The compiler
    decides the same thing by whether the keyword is present."""

    def __repr__(self) -> str:
        return "<not given>"


_NOT_GIVEN: Any = _NotGiven()


class ToggleButton(BaseWidget):
    """A button that stays pressed — Flutter's ``ToggleButtons`` segment and
    ``IconButton(isSelected=…)``, the design system's toggle button
    (``toggle-group.html``). Not the on/off :class:`Switch`: this is a
    formatting-toolbar button (Bold, Italic) or a filter that reads as "on"
    once pressed.

    **Its content is its children**, any widgets in any order, so an icon
    before the text and an icon after it are the same widget with its
    children swapped — not two settings::

        ToggleButton(Text("Bold"), selected=self.bold, on_change=self.set_bold)
        ToggleButton(Icon("bookmark"), Text("Save"), ...)
        ToggleButton(Text("Like"), Icon("thumb-up"), ...)
        ToggleButton(Dot(), Text("Live"), ...)
        ToggleButton(Icon("star"), label="Favourite", ...)   # icon only

    A ``Text`` or an ``Icon`` inside takes the toggle's font, colour and icon
    size unless it sets its own. A toggle whose only child is an ``Icon`` is
    drawn as the design's square icon button, and needs ``label=`` — its
    accessible name, since there is no text to read; the compiler refuses
    one without it.

    Standalone it is controlled: ``selected`` is the state and
    ``on_change`` receives the new boolean. Inside a managed
    :class:`ToggleGroup` the group owns the selection instead, and the
    button only names itself with ``value``.

    ``variant`` (``"default"`` | ``"ghost"``) and ``size`` (``"sm"`` |
    ``"md"`` | ``"lg"``) follow :class:`Button`'s naming and are literals;
    ``selected``, ``disabled``, ``value`` and ``label`` may be dynamic.
    ``style=`` takes the same CSS overrides as every surface widget, plus a
    ``":selected"`` state block; the ``--toggle-btn-*`` tokens are the
    preferred theming hook.
    """

    widget_type = "ToggleButton"

    def __init__(
        self,
        *children: Any,
        selected: bool | Binding = False,
        on_change: Callable | None = None,
        value: Any = None,
        variant: Literal["default", "ghost"] = "default",
        size: Literal["sm", "md", "lg"] = "md",
        disabled: bool | Binding = False,
        label: str | Binding | None = None,
        style: dict[str, Any] | None = None,
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, disabled=disabled, **kwargs)
        self.content = list(children)
        self.selected = selected
        self.on_change = on_change
        self.value = value
        self.variant = variant
        self.size = size
        self.label = label
        self.style = style

    def children(self) -> list[Any]:
        return list(self.content)

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {"selected": self.selected}
        if self.value is not None:
            p["value"] = self.value
        if self.variant != "default":
            p["variant"] = self.variant
        if self.size != "md":
            p["size"] = self.size
        if self.label is not None:
            p["label"] = self.label
        if self.style:
            p["style"] = self.style
        return p


class ToggleGroup(BaseWidget):
    """Toggle buttons fused into one segmented pill — Flutter's
    ``SegmentedButton`` when it owns the selection, ``ToggleButtons`` when
    it only groups them. A hairline divider sits between each pair and only
    the two outer ends are rounded.

    **Managed** — pass ``value=`` and the group holds the selection, like
    ``SegmentedButton(selected=…, onSelectionChanged=…)``. Every child names
    itself with ``value=`` and sets neither ``selected`` nor ``on_change``::

        ToggleGroup(
            ToggleButton(Text("Day"), value="day"),
            ToggleButton(Text("Week"), value="week"),
            ToggleButton(Text("Month"), value="month"),
            value=self.span, on_change=self.set_span,
        )

    Single-select hands ``on_change`` the chosen value. ``multiple=True``
    makes ``value`` a list, and ``on_change`` gets the new list in the
    children's order. ``allow_empty`` (default ``False``, as in Flutter)
    decides whether the last selected button can be pressed off, leaving
    ``None`` or ``[]``. Inside a :class:`Field` a managed group answers for
    the field's value, so ``required`` and the other validators work.

    **Visual** — no ``value=``: the buttons are fused but each is still a
    standalone toggle with its own ``selected`` and ``on_change``, the
    design's formatting toolbar::

        ToggleGroup(
            ToggleButton(Icon("bold"), label="Bold",
                         selected=self.bold, on_change=self.set_bold),
            ToggleButton(Icon("italic"), label="Italic",
                         selected=self.italic, on_change=self.set_italic),
            variant="ghost",
        )

    ``variant`` and ``size`` apply to every child that does not set its own.
    ``direction`` is ``"horizontal"`` or ``"vertical"``; ``fill`` stretches
    the group and splits the space evenly; ``spaced`` keeps each button's
    own pill with a 4px gap and no dividers. ``label`` is the group's
    accessible name. The group is one Tab stop: arrow keys move between its
    buttons, Home and End jump to the ends, Space or Enter presses.
    """

    widget_type = "ToggleGroup"

    def __init__(
        self,
        *buttons: ToggleButton,
        value: Any = _NOT_GIVEN,
        on_change: Callable | None = None,
        multiple: bool = False,
        allow_empty: bool = False,
        direction: Literal["horizontal", "vertical"] = "horizontal",
        fill: bool = False,
        spaced: bool = False,
        variant: Literal["default", "ghost"] | None = None,
        size: Literal["sm", "md", "lg"] | None = None,
        disabled: bool | Binding = False,
        label: str | Binding | None = None,
        style: dict[str, Any] | None = None,
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, disabled=disabled, **kwargs)
        self.buttons = list(buttons)
        self.managed = value is not _NOT_GIVEN
        self.value = None if value is _NOT_GIVEN else value
        self.on_change = on_change
        self.multiple = multiple
        self.allow_empty = allow_empty
        self.direction = direction
        self.fill = fill
        self.spaced = spaced
        self.variant = variant
        self.size = size
        self.label = label
        self.style = style

    def children(self) -> list[Any]:
        return list(self.buttons)

    def props(self) -> dict[str, Any]:
        p: dict[str, Any] = {}
        if self.managed:
            p["managed"] = True
            p["value"] = self.value
            if self.multiple:
                p["multiple"] = True
            if self.allow_empty:
                p["allowEmpty"] = True
        if self.direction != "horizontal":
            p["direction"] = self.direction
        for flag in ("fill", "spaced"):
            if getattr(self, flag):
                p[flag] = True
        for name in ("variant", "size", "label", "style"):
            if getattr(self, name) is not None:
                p[name] = getattr(self, name)
        return p


class Select(BaseWidget):
    """A picker, inspired by Flutter's ``DropdownButton``.

    ``options`` is a list of strings (each is both the option value and its
    label), or of dicts when an option carries more than a name::

        {"value": "ada", "label": "Ada Lovelace", "meta": "@ada",
         "icon": "user"}          # or "dot": "green", or "avatar": "AL"

    Either form may be a literal or a State field, so the choices can change
    reactively. ``value`` is the controlled selection; ``on_change`` receives
    the selected **value**.

    **It is a field whose control is the picker**, so it takes the same
    ``label`` / ``hint`` / ``message`` / ``status`` / ``size`` as
    :class:`~workpeg.ui.widgets.fields.Input` and renders them identically —
    a select that can go red goes red the same way an email field does, not
    through a second code path. It is drawn rather than native because a
    native ``<select>`` cannot carry a marker, a meta column or a filter row,
    and its popup cannot be styled at all.

    ``search=True`` adds the filter row, which earns its keystroke past a
    couple of dozen options and is noise below that.

    Compiler API::

        class Picker(App):
            colour = State("red")

            def set_colour(self, value):     # receives the selected option
                self.colour = value

            def build(self):
                return Select(
                    options=["red", "green", "blue"],
                    value=self.colour,
                    on_change=self.set_colour,
                    label="Colour",
                )
    """

    widget_type = "Select"

    def __init__(
        self,
        *,
        options: list,
        value: str | Binding = "",
        on_change: Callable | None = None,
        placeholder: str = "",
        label: str | None = None,
        hint: str | None = None,
        message: str | None = None,
        status: str | None = None,
        size: str = "md",
        search: bool = False,
        disabled: bool = False,
        key: str | None = None,
        visible: bool | Binding = True,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key,
            visible=visible,
            disabled=disabled,
            metadata=metadata,
        )
        self.options = options
        self.value = value
        self.on_change = on_change
        self.placeholder = placeholder
        self.label = label
        self.hint = hint
        self.message = message
        self.status = status
        self.size = size
        self.search = search

    def props(self) -> dict[str, Any]:
        # The field surface is reported too, not just the choices: a
        # consumer that reads props() (rather than compiling) would
        # otherwise see a Select with no label and no status and render a
        # different widget from the one the app declared.
        p: dict[str, Any] = {"options": self.options, "value": self.value}
        for name in ("placeholder", "label", "hint", "message", "status"):
            value = getattr(self, name)
            if value:
                p[name] = value
        if self.size != "md":
            p["size"] = self.size
        if self.search:
            p["search"] = True
        return p


