class ChatInput(BaseWidget):
    """A chat composer — a ``contenteditable`` box that grows with its content,
    like the input in an AI chat app. You type Markdown as plain text; **Enter**
    submits (``on_submit`` receives the text), **Shift+Enter** inserts a newline.

    It is **injection-safe by construction**: the element is
    ``contenteditable="plaintext-only"`` (the browser keeps it plain text and
    strips formatting from pastes; a fallback sanitises pastes to plain text),
    and the runtime only ever reads/writes its ``innerText`` — never ``innerHTML``
    — so no markup or script can enter. Pair it with :class:`Markdown` (which
    renders the Markdown back out, also safely) for a full chat::

    Pass ``markdown=True`` for **live formatting as you type**, like Slack: as you
    write ``**bold**``, `` `code` ``, ``# headings`` or ``- lists``, the composer
    styles them in place while keeping the syntax visible — and the *value* stays
    the raw Markdown string (so ``on_submit`` / :class:`Markdown` round-trip
    unchanged). It stays injection-safe: the box is rebuilt from its ``innerText``
    on every edit by *creating DOM nodes* (never ``innerHTML``), so nothing the
    user types can become live markup or script::

        class Chat(App):
            draft = State("")
            messages = State([])

            def set_draft(self, v): self.draft = v
            def send(self, text):
                self.messages = self.messages + [text]
                self.draft = ""              # clears the composer

            def build(self):
                return ChatInput(value=self.draft, on_change=self.set_draft,
                                 on_submit=self.send,
                                 placeholder="Message… (Markdown ok)")
    """

    widget_type = "ChatInput"

    def __init__(
        self,
        *,
        value: str | Binding = "",
        on_change: Callable | None = None,
        on_submit: Callable | None = None,
        placeholder: str = "",
        min_rows: int = 1,
        max_rows: int = 8,
        markdown: bool = False,
        disabled: bool = False,
        autofocus: bool = False,
        key: str | None = None,
        visible: bool | Binding = True,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key, visible=visible, disabled=disabled, metadata=metadata,
        )
        self.value = value
        self.on_change = on_change
        self.on_submit = on_submit
        self.placeholder = placeholder
        self.min_rows = min_rows
        self.max_rows = max_rows
        self.markdown = markdown
        self.autofocus = autofocus

    def props(self) -> dict[str, Any]:
        return {
            "value": self.value,
            "placeholder": self.placeholder,
            "min_rows": self.min_rows,
            "max_rows": self.max_rows,
            "markdown": self.markdown,
        }


class EditableText(BaseWidget):
    """An edit-in-place text box that fills whatever holds it.

    A ``contenteditable`` div rather than an ``<input>``, which buys one
    thing an input cannot: it takes the size of its container instead of
    carrying an intrinsic width. That is what makes it usable inside a table
    cell, where an ``<input>`` refuses to shrink below its own idea of how
    wide it should be and forces the whole column wider::

        Table(
            TableHeader(TableCell(title="Name"), TableCell(title="Note")),
            *[TableRow(
                TableCell(title=row.name),
                TableCell(EditableText(value=row.note,
                                       on_change=self.save_note)),
              ) for row in self.rows],
        )

    ``on_change`` fires as the text changes; ``on_submit`` fires on **Enter**,
    with **Shift+Enter** inserting a newline instead.

    **Injection-safe by construction**, which matters more here than in most
    widgets: a table cell holds workspace data, so a payload that survived one
    edit would be stored and replayed to everyone who later opened the table.
    Four vectors, all closed:

    * The element is ``contenteditable="plaintext-only"``, and the runtime
      **reads the attribute back** — engines that do not support that value
      ignore it silently rather than raising, so without the read-back you
      would have a rich contenteditable on every one of them. Where it is not
      supported the runtime falls back to ``"true"`` plus a paste sanitiser.
    * Its value is read with ``innerText`` and written with ``innerText``.
      Never ``innerHTML``, in either direction.
    * A **paste** is stripped to plain text before it lands.
    * So is a **drop** — dragging a selection out of another page fires
      ``drop``, not ``paste``, and would otherwise insert live markup.

    ``fill=False`` turns off the stretch if you want it to size to its
    content instead.
    """

    widget_type = "EditableText"

    def __init__(
        self,
        *,
        value: str | Binding = "",
        on_change: Callable | None = None,
        on_submit: Callable | None = None,
        placeholder: str = "",
        multiline: bool = False,
        fill: bool = True,
        disabled: bool = False,
        autofocus: bool = False,
        key: str | None = None,
        visible: bool | Binding = True,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key, visible=visible, disabled=disabled, metadata=metadata,
        )
        self.value = value
        self.on_change = on_change
        self.on_submit = on_submit
        self.placeholder = placeholder
        self.multiline = multiline
        self.fill = fill
        self.autofocus = autofocus

    def props(self) -> dict[str, Any]:
        return {
            "value": self.value,
            "placeholder": self.placeholder,
            "multiline": self.multiline,
            "fill": self.fill,
        }


class SignInWithWorkpeg(BaseWidget):
    """A "Sign in with Workpeg" button.

    The button is a convenience over :class:`workpeg.auth.WorkpegAuth`, not a
    second implementation of it. It renders an anchor to an authorization URL
    the SDK builds; everything it does is available programmatically for an
    application that starts sign-in from its own logic instead::

        from workpeg.auth import WorkpegAuth
        start = WorkpegAuth(client_id=..., redirect_uri=...).begin()

    Compiler API::

        SignInWithWorkpeg(client_id="acme",
                          redirect_uri="https://acme.test/auth/callback")

        SignInWithWorkpeg(..., label="Continue with Workpeg")
        SignInWithWorkpeg(..., variant="secondary", full_width=True)

    WHAT THE CALLER MUST STILL DO. The button starts the flow; it cannot
    finish it. ``begin()`` produces a ``state`` and a PKCE ``code_verifier``
    that have to be kept against the browser session and checked at the
    callback — that is what ties the callback to the sign-in this application
    started. Pass ``start=`` when you have created them yourself, which is the
    right thing for anything with a server. Without it the button builds a URL
    with a fresh pair at COMPILE time, which is only appropriate for a
    single-user local build.

    WHO SIGNS IN. A Workpeg identity is a person AND the business they chose,
    so one human in three businesses can produce three different subjects
    sharing one email. Key accounts on the subject.
    """

    widget_type = "Link"

    def __init__(
        self,
        *,
        client_id: str = "",
        redirect_uri: str = "",
        start: Any = None,
        issuer: str = "https://api.workpeg.com",
        scope: str = "openid profile email",
        label: str = "Sign in with Workpeg",
        variant: Literal["primary", "secondary", "tertiary"] = "primary",
        full_width: bool = False,
        key: str | None = None,
        visible: bool | Binding = True,
        disabled: bool | Binding = False,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(
            key=key,
            visible=visible,
            disabled=disabled,
            metadata=metadata,
        )

        if start is None:
            if not client_id or not redirect_uri:
                raise ValueError(
                    "SignInWithWorkpeg needs either start= (from "
                    "WorkpegAuth.begin(), which is what an application with a "
                    "server should use) or both client_id= and redirect_uri=."
                )
            from workpeg.auth import WorkpegAuth

            start = WorkpegAuth(
                client_id=client_id,
                redirect_uri=redirect_uri,
                issuer=issuer,
                scope=scope,
            ).begin()

        self.start = start
        self.label = label
        self.variant = variant
        self.full_width = full_width

    @property
    def href(self) -> str:
        return self.start.url

    def props(self) -> dict[str, Any]:
        return {
            "href": self.start.url,
            "label": self.label,
            "variant": self.variant,
            "full_width": self.full_width,
            "icon": "brand-workpeg",
            # Top-level navigation, not a new tab: the flow has to come back
            # to this origin, and a popup that a browser blocks strands the
            # person with no way to sign in.
            "rel": "noopener",
        }
